from ielts_h import rstory
READ3 = [rstory("A Short Mock Passage", "Mini mock",
 "The first public libraries in Britain opened in the nineteenth century. Before that, books were expensive, and only wealthy people could afford them. Libraries gave ordinary families a chance to read for free. By 1900, there were more than 300 libraries across the country. Today, many libraries offer computers and classes as well as books, although some have closed because of budget cuts. Supporters argue that libraries remain essential for communities, especially for people without internet at home.",
 "Perpustakaan umum pertama di Inggris dibuka pada abad kesembilan belas. Sebelum itu, buku mahal dan hanya orang kaya yang mampu membelinya. Perpustakaan memberi keluarga biasa kesempatan untuk membaca secara gratis. Pada tahun 1900, ada lebih dari 300 perpustakaan di seluruh negeri. Kini, banyak perpustakaan menawarkan komputer dan kelas selain buku, meskipun sebagian tutup karena pemotongan anggaran. Para pendukung berpendapat bahwa perpustakaan tetap penting bagi masyarakat, terutama bagi orang yang tidak punya internet di rumah.",
 [("Heading terbaik untuk seluruh teks?", "The history and value of libraries", "How to write a book", "The cost of the internet", "Famous British writers", "Ide utama teks."),
  ("Scanning: berapa perpustakaan pada tahun 1900?", "lebih dari 300", "lebih dari 30", "lebih dari 3.000", "sekitar 100", "Teks: more than 300."),
  ("Kata 'essential' paling dekat dengan...", "sangat penting", "mahal", "lama", "kecil", "Essential = sangat penting.")],
 [("Libraries opened in Britain in the nineteenth century.", 'T', "Teks menyebutnya."),
  ("Before libraries opened, only wealthy people could afford books.", 'T', "Teks menyebutnya."),
  ("Libraries are used most by students.", 'N', "Tidak disebut.")],
 [("Perpustakaan memberi kesempatan membaca gratis.", "Libraries let families read for ___.", "free", "Teks: for free."),
  ("Beberapa perpustakaan tutup karena pemotongan anggaran.", "Some closed because of budget ___.", "cuts", "Teks: budget cuts.")])]
